const { execFileSync } = await import("child_process");
const out = execFileSync("npm", ["run", "test:flow-annotations"], { cwd: $root, encoding: "utf8", stdio: ["pipe", "pipe", "pipe"] });
return { verified: out.includes("flow annotation repair verified") };

const { loadConfig } = await import($root + "/packages/main/dist/core/config.js");
const { scan, extractFlows } = await import($root + "/packages/main/dist/tasks/extract.js");
const { join } = await import("path");
const config = loadConfig($root);
const tasks = scan(join($root, config.scanRoot));
const chain = extractFlows(tasks).find((flow) => flow.name === "story-lifecycle");
return { hasStep2: chain.steps.some((step) => step.step === 2 && step.functionName === "story_advance") };

const { loadConfig } = await import($root + "/packages/main/dist/core/config.js");
const { scan, extractFlows } = await import($root + "/packages/main/dist/tasks/extract.js");
const { validateFlows } = await import($root + "/packages/main/dist/tasks/validate.js");
const { join } = await import("path");
const config = loadConfig($root);
const tasks = scan(join($root, config.scanRoot));
const chains = extractFlows(tasks);
const issues = validateFlows(chains, tasks).issues.filter((issue) => issue.flow === "story-lifecycle");
return { noGap: issues.every((issue) => !issue.msg.includes("gap between step 1 and 3")) };

const { loadConfig } = await import($root + "/packages/main/dist/core/config.js");
const { validate } = await import($root + "/packages/main/dist/tasks/validate.js");
const { join } = await import("path");
const config = loadConfig($root);
const errors = validate(join($root, config.scanRoot)).errors.filter((issue) => issue.loc.startsWith("src/handlers/summary.ts"));
return { noErrors: errors.length === 0 };

const { readFileSync } = await import("fs");
const text = readFileSync($root + "/packages/main/src/handlers/summary.ts", "utf8");
return { hasChecklist: text.includes("@checklist"), hasType: text.includes("@type"), hasPriority: text.includes("@priority"), hasChanges: text.includes("@changes") };

const { readFileSync } = await import("fs");
const text = readFileSync($root + "/packages/main/src/handlers/summary.ts", "utf8");
return { noFileLevelTest: !text.includes("@test") };

const { StoryStore } = await import($root + "/packages/main/dist/core/store.js");
const { checkConvergence } = await import($root + "/packages/main/dist/tasks/gap-analyze.js");
const store = new StoryStore($root);
const result = checkConvergence($root, store);
const flowCheck = result.checks.find((check) => check.name === "Flow 链路完整");
return { flowPassed: flowCheck?.passed === true };

const { StoryStore } = await import($root + "/packages/main/dist/core/store.js");
const { checkConvergence } = await import($root + "/packages/main/dist/tasks/gap-analyze.js");
const store = new StoryStore($root);
const result = checkConvergence($root, store);
const codeCheck = result.checks.find((check) => check.name === "代码注释合规");
return { codePassed: codeCheck?.passed === true };

const { execFileSync } = await import("child_process");
const { StoryStore } = await import($root + "/packages/main/dist/core/store.js");
const { checkConvergence } = await import($root + "/packages/main/dist/tasks/gap-analyze.js");
const out = execFileSync("npm", ["run", "test:flow-annotations"], { cwd: $root, encoding: "utf8", stdio: ["pipe", "pipe", "pipe"] });
const store = new StoryStore($root);
const result = checkConvergence($root, store);
return { scriptPass: out.includes("flow annotation repair verified"), convergenceStillHasOtherWork: result.converged === false };
